import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Equipment from './Equipment';
import EquipmentSearch from './EquipmentSearch';
import styled from 'styled-components';

// Styled components
const Container = styled.div`
  display: flex;
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
`;

const Content = styled.div`
  flex: 3;
`;

const Sidebar = styled.div`
  flex: 1;
  padding: 15px;
  border-left: 1px solid #ddd;
  margin-left: 20px;
  max-height: 600px;
  overflow-y: auto;
  position: relative;
  background-color: #f7f9fc;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const Modal = styled.div`
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: white;
  padding: 20px;
  z-index: 1000;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
  border-radius: 10px;
`;

const Overlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.7);
  z-index: 999;
`;

const TabContainer = styled.div`
  display: flex;
  margin-top: 20px;
  button {
    flex: 1;
    padding: 10px;
    cursor: pointer;
    background: #f2f2f2;
    border: none;
    outline: none;
    &:hover {
      background: #ddd;
    }
    &.active {
      background: #ddd;
      font-weight: bold;
    }
  }
`;

const EquipmentPage = () => {
  const [equipmentData, setEquipmentData] = useState([]);
  const [selection, setSelection] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [activeTab, setActiveTab] = useState('beginner');
  const itemsPerPage = 20;

  // Fetch equipment data
  const fetchData = async (searchTerm = '', category = 'all', minPrice = '', maxPrice = '') => {
    setLoading(true);
    try {
      const response = await axios.get('/api/equipment', {
        params: { page: currentPage, search: searchTerm, category, min_price: minPrice, max_price: maxPrice },
      });
      setEquipmentData(response.data.equipment);
      setTotalPages(response.data.total_pages);
      setLoading(false);
    } catch (error) {
      setError('Failed to load data');
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [currentPage]);

  // Modal handlers
  const openModal = (item) => {
    setSelectedItem(item);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedItem(null);
  };

  // Handle adding and removing items from the selection
  const addToSelection = async (equipment) => { /* unchanged */ };
  const removeFromSelection = async (itemId) => { /* unchanged */ };

  // Pagination controls
  const nextPage = () => { /* unchanged */ };
  const prevPage = () => { /* unchanged */ };

  // Search function
  const handleSearch = (searchTerm, category, minPrice, maxPrice) => { /* unchanged */ };

  // Sidebar item click
  const handleSidebarItemClick = (item) => openModal(item);

  // Render
  return (
    <Container>
      <Content>
        <EquipmentSearch onSearch={handleSearch} />
        <Equipment equipment={equipmentData} onAddToSelection={addToSelection} />
        <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
          <button onClick={prevPage} disabled={currentPage === 1}>Previous</button>
          <span style={{ margin: '0 10px' }}>Page {currentPage} of {totalPages}</span>
          <button onClick={nextPage} disabled={currentPage === totalPages}>Next</button>
        </div>

        {/* Tabbed Information Section */}
        <TabContainer>
          {['beginner', 'training', 'expert'].map((tab) => (
            <button
              key={tab}
              className={activeTab === tab ? 'active' : ''}
              onClick={() => setActiveTab(tab)}
            >
              {tab.charAt(0).toUpperCase() + tab.slice(1)}
            </button>
          ))}
        </TabContainer>

        {activeTab === 'beginner' && <p>Beginner tips: Basic gear, budget-friendly options...</p>}
        {activeTab === 'training' && <p>Training tips: Durable equipment, mid-range budget...</p>}
        {activeTab === 'expert' && <p>Expert tips: High-performance gear, investment in quality...</p>}
      </Content>

      <Sidebar>
        <h2>Your Selection</h2>
        <ul>
          {selection.map((item) => (
            <li key={item.id} onClick={() => handleSidebarItemClick(item)}>
              {item.name || 'Unnamed Item'} - ${item.price || '0.00'}
              <button onClick={(e) => { e.stopPropagation(); removeFromSelection(item.id); }}>Remove</button>
            </li>
          ))}
        </ul>
        <div>Total: ${selection.reduce((sum, item) => sum + (item.price || 0), 0)}</div>
      </Sidebar>

      {isModalOpen && (
        <>
          <Overlay onClick={closeModal} />
          <Modal>
            <h2>{selectedItem.name}</h2>
            <p>Price: ${selectedItem.price}</p>
            <p>{selectedItem.description}</p>
            <button onClick={closeModal}>Close</button>
          </Modal>
        </>
      )}
    </Container>
  );
};

export default EquipmentPage;
